WITH l AS(SELECT "layoutJson" j,"version","publishedAt" FROM "StorePosLayout" WHERE "storeId"='kat-store'), refs AS(
SELECT jsonb_array_elements_text(COALESCE(q->'productCodes','[]'::jsonb)) id FROM l,jsonb_array_elements(j->'quickKeys') q
UNION SELECT jsonb_array_elements_text(COALESCE(c->'productCodes','[]'::jsonb)) FROM l,jsonb_array_elements(j->'categories') c
UNION SELECT jsonb_array_elements_text(COALESCE(ch->'productCodes','[]'::jsonb)) FROM l,jsonb_array_elements(j->'categories') c,jsonb_array_elements(COALESCE(c->'children','[]'::jsonb)) ch)
SELECT NOW() AS "observedAt",
(SELECT jsonb_build_object('version',"version",'publishedAt',"publishedAt",'quickSlots',jsonb_array_length(j->'quickKeys'),'categorySlots',jsonb_array_length(j->'categories'),'mappedProducts',(SELECT COUNT(*) FROM refs)) FROM l) AS layout,
(SELECT jsonb_build_object('activeProducts',COUNT(*),'missingVatDepartment',COUNT(*) FILTER(WHERE vd."id" IS NULL),'nonpositivePrice',COUNT(*) FILTER(WHERE COALESCE(sp."salePrice",p."salePrice")<=0)) FROM "Product" p JOIN "StoreProduct" sp ON sp."productId"=p."id" AND sp."storeId"='kat-store' LEFT JOIN "ManagementVatDepartment" vd ON vd."id"=p."vatDepartmentId" AND vd."companyId"=p."companyId" WHERE p."companyId"='pilot-company' AND p."active" AND sp."active") AS catalog,
(SELECT jsonb_agg(jsonb_build_object('sku',p."sku",'id',p."id",'name',p."name",'vatRate',p."vatRate",'mappedToButton',EXISTS(SELECT 1 FROM refs WHERE refs.id=p."id"))) FROM "Product" p JOIN "StoreProduct" sp ON sp."productId"=p."id" AND sp."storeId"='kat-store' LEFT JOIN "ManagementVatDepartment" vd ON vd."id"=p."vatDepartmentId" AND vd."companyId"=p."companyId" WHERE p."companyId"='pilot-company' AND p."active" AND sp."active" AND vd."id" IS NULL) AS "missingDepartmentProducts",
(SELECT jsonb_agg(jsonb_build_object('terminal',d."metadata"->>'rbsCapDriverV1TerminalPos','fiscalDevice',d."metadata"->>'rbsCapDriverV1FiscalDeviceCode','lastSeenAt',d."lastSeenAt",'writerPoll',d."metadata"->>'rbsCapDriverV1WriterPoll','status',d."status")) FROM "CloudDevice" d WHERE d."storeId"='kat-store' AND d."id" IN ('25c89d85-c85b-4ebe-a4eb-7a7e7911754c','573b729e-83bd-4abf-82ba-0ad119333c8e')) AS writers,
(SELECT COUNT(*) FROM "RbsCapDriverV1Request" WHERE "storeId"='kat-store' AND "status" NOT IN ('SALE_COMMITTED','DECLINED')) AS "unresolvedFiscalRequests",
(SELECT jsonb_agg(jsonb_build_object('terminal',"terminalPos",'status',"status",'cash',"cashSales",'card',"cardSales")) FROM "CashShiftSession" WHERE "storeId"='kat-store' AND "status"='OPEN') AS "openShifts",
(SELECT jsonb_build_object('parents',COUNT(*),'badFee',COUNT(*) FILTER(WHERE s."quantity"<>1 OR s."salePrice"<>0.05),'embeddedFeeNonzero',COUNT(*) FILTER(WHERE COALESCE(ps."environmentalFee",0)<>0)) FROM "ProductSetItem" s LEFT JOIN "PreparationProductSettings" ps ON ps."productId"=s."productId" AND ps."companyId"=s."companyId" WHERE s."companyId"='pilot-company' AND s."relatedProductId"='0112e532-4761-44c5-ac51-c16e8cca7cb4') AS "coffeeFee",
(SELECT jsonb_agg(jsonb_build_object('status',"status",'completedAt',"completedAt",'restoreCheck',"dryRunStatus")) FROM(SELECT * FROM "PlatformBackupRun" ORDER BY "startedAt" DESC LIMIT 3)b) AS backups
